window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-56f95dc2beca6c02"]={"versions": [{"id": "FIG-56f95dc2beca6c02", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfigurationsstruktur (ECU Configuration Parameter Definition, ECUC) des AUTOSAR Crypto Service Managers (CSM). Es spezifiziert die Container-Hierarchie des übergeordneten Konfigurationscontainers <code>CsmPrimitives</code> und dessen zulässige Sub-Container für kryptografische Primitiven und Schlüsselmanagement-Operationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine hierarchische Kompositionsstruktur basierend auf der Metaklasse <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\"><li><strong>Übergeordneter Container:</strong>\n<ul class=\"fig-list\"><li><code>CsmPrimitives</code> (Multiplizität: <code>0..*</code>)\n</li></ul>\n</li><li><strong>Untergeordnete Sub-Container (<code>+subContainer</code>), jeweils mit Multiplizität <code>0..1</code>:</strong>\n<ul class=\"fig-list\"><li>Kryptografische Algorithmen &amp; Primitiven:\n<ul class=\"fig-list\"><li><code>CsmHash</code>\n</li><li><code>CsmMacGenerate</code>\n</li><li><code>CsmMacVerify</code>\n</li><li><code>CsmEncrypt</code>\n</li><li><code>CsmDecrypt</code>\n</li><li><code>CsmAEADEncrypt</code>\n</li><li><code>CsmAEADDecrypt</code>\n</li><li><code>CsmSignatureGenerate</code>\n</li><li><code>CsmSignatureVerify</code>\n</li><li><code>CsmRandomGenerate</code>\n</li></ul>\n</li><li>Schlüsselmanagement- und Zustandsoperationen:\n<ul class=\"fig-list\"><li><code>CsmJobKeySetValid</code>\n</li><li><code>CsmJobKeySetInvalid</code>\n</li><li><code>CsmJobRandomSeed</code>\n</li><li><code>CsmJobKeyDerive</code>\n</li><li><code>CsmJobKeyGenerate</code>\n</li><li><code>CsmJobKeyExchangeCalcPubVal</code>\n</li><li><code>CsmJobKeyExchangeCalcSecret</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle Sub-Container sind über Kompositionsbeziehungen (<code>+subContainer</code>, ausgefüllte Raute an <code>CsmPrimitives</code>) an den Elterncontainer angebunden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge dar. Es definiert die statische Schachtelung für den ECUC-Generierungsprozess und die Parametrierung der kryptografischen Primitiven vor der Kompilierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ für die Konfigurationsstruktur des CSM im BSW-Stack. Innerhalb einer <code>CsmPrimitives</code>-Instanz dürfen die 17 definierten Sub-Container optional jeweils maximal einmal konfiguriert werden (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Die Konfigurationstools müssen sicherstellen, dass nur spezifizierte Primitiv-Container unterhalb von <code>CsmPrimitives</code> instanziiert werden.</p>"}, {"id": "FIG-0f5de4b9e6eb17ad", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfigurationsstruktur (ECU Configuration Parameter Definition, ECUC) des AUTOSAR Crypto Service Managers (CSM). Es spezifiziert die Container-Hierarchie des übergeordneten Konfigurationscontainers <code>CsmPrimitives</code> und dessen zulässige Sub-Container für kryptografische Primitiven und Schlüsselmanagement-Operationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine hierarchische Kompositionsstruktur basierend auf der Metaklasse <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\"><li><strong>Übergeordneter Container:</strong>\n<ul class=\"fig-list\"><li><code>CsmPrimitives</code> (Multiplizität: <code>0..*</code>)\n</li></ul>\n</li><li><strong>Untergeordnete Sub-Container (<code>+subContainer</code>), jeweils mit Multiplizität <code>0..1</code>:</strong>\n<ul class=\"fig-list\"><li>Kryptografische Algorithmen &amp; Primitiven:\n<ul class=\"fig-list\"><li><code>CsmHash</code>\n</li><li><code>CsmMacGenerate</code>\n</li><li><code>CsmMacVerify</code>\n</li><li><code>CsmEncrypt</code>\n</li><li><code>CsmDecrypt</code>\n</li><li><code>CsmAEADEncrypt</code>\n</li><li><code>CsmAEADDecrypt</code>\n</li><li><code>CsmSignatureGenerate</code>\n</li><li><code>CsmSignatureVerify</code>\n</li><li><code>CsmRandomGenerate</code>\n</li><li><code>CsmCustom</code>\n</li></ul>\n</li><li>Schlüsselmanagement- und Zustandsoperationen:\n<ul class=\"fig-list\"><li><code>CsmJobKeySetValid</code>\n</li><li><code>CsmJobKeySetInvalid</code>\n</li><li><code>CsmJobRandomSeed</code>\n</li><li><code>CsmJobKeyDerive</code>\n</li><li><code>CsmJobKeyGenerate</code>\n</li><li><code>CsmJobKeyExchangeCalcPubVal</code>\n</li><li><code>CsmJobKeyExchangeCalcSecret</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle Sub-Container sind über Kompositionsbeziehungen (<code>+subContainer</code>, ausgefüllte Raute an <code>CsmPrimitives</code>) an den Elterncontainer angebunden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge dar. Es definiert die statische Schachtelung für den ECUC-Generierungsprozess und die Parametrierung der kryptografischen Primitiven vor der Kompilierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ für die Konfigurationsstruktur des CSM im BSW-Stack. Innerhalb einer <code>CsmPrimitives</code>-Instanz dürfen die 18 definierten Sub-Container optional jeweils maximal einmal konfiguriert werden (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Die Konfigurationstools müssen sicherstellen, dass nur spezifizierte Primitiv-Container unterhalb von <code>CsmPrimitives</code> instanziiert werden.</p>"}], "trans": [{"from": "FIG-56f95dc2beca6c02", "to": "FIG-0f5de4b9e6eb17ad", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neuer Kind-Container <code>CsmCustom: EcucParamConfContainerDef</code> über Komposition <code>+subContainer</code> an <code>CsmPrimitives</code> angebunden mit Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.\n</li></ul>"}]};
